"任何房间：出征多带 {0} 件宝物。契合「防御」：武器：伤害 +{1}%，命中溅射并减速；其它：再多 {2} 名守卫。": "Toute salle : reliques en expédition +{0}. Salle « Défense » : armes : dégâts +{1} %, éclaboussure et ralentissement à l'impact ; autres : gardes +{2}.",
"任何房间：出征带回的物资 +{0}%。契合「运势」：物资再 +{1}%，每场战斗初始积分倍率 +{2}。": "Toute salle : provisions rapportées +{0} %. Salle « Fortune » : provisions encore +{1} %, multiplicateur de points de départ +{2} à chaque combat.",
"任何房间：出征视野 +{0}，初始积分倍率 +{1}。契合「运势 / 特殊」：出征地图一开始就全亮，积分倍率再 +{2}。": "Toute salle : vision d'expédition +{0}, multiplicateur de points de départ +{1}. Salle « Fortune / Spécial » : carte d'expédition entièrement révélée au départ, multiplicateur encore +{2}.",
"任何房间：出征部队攻击 +{0}%。契合「训练」：领袖出征得到的经验 +{1}%。": "Toute salle : attaque des troupes en expédition +{0} %. Salle « Entraînement » : XP d'expédition du chef +{1} %.",
"任何房间：出征部队生命 +{0}%。契合「医疗」：医院回复 +{1}%，领袖每天再回 {2}%。": "Toute salle : PV des troupes en expédition +{0} %. Salle « Médical » : soins de l'hôpital +{1} %, le chef récupère encore {2} % par jour.",
"任何房间：图纸掉率 +{0}%。契合「科幻」：基地每天 +{1} 灵魂碎片。": "Toute salle : taux d'obtention de plans +{0} %. Salle « Science-fiction » : base +{1} éclats d'âme par jour.",
"任何房间：图纸掉率 +{0}%。契合「锻造」：打造时 {1}% 概率多得一件。": "Toute salle : taux d'obtention de plans +{0} %. Salle « Forge » : {1} % de chances d'une relique en plus à la forge.",
"任何房间：基地每天 +{0} 灵魂碎片。契合「魔法」：基地每天再 +{1} 灵魂碎片。": "Toute salle : base +{0} éclats d'âme par jour. Salle « Magie » : encore +{1} par jour.",
"任何房间：基地每天 +{0} 物资。契合「后勤」：这个房间自己的效果 ×{1}。": "Toute salle : base +{0} provisions par jour. Salle « Logistique » : effet propre de cette salle ×{1}.",
"任何房间：基地每天 +{0} 物资，领袖每天获得 {1} 经验。契合「后勤 / 自然」：这个房间自己的效果 ×{2}。": "Toute salle : base +{0} provisions par jour, le chef gagne {1} XP par jour. Salle « Logistique / Nature » : effet propre de cette salle ×{2}.",
"任何房间：宝物打造费用 -{0}%。契合「锻造 / 武器」：锻造：{1}% 概率品质 +{2}；武器：伤害 +{3}%。": "Toute salle : coût de forge des reliques -{0} %. Salle « Forge / Arme » : forge : {1} % de chances de qualité +{2} ; armes : dégâts +{3} %.",
"任何房间：建造时间减半，建成返还 {0}% 物资。契合「奇观」：返还提高到 {1}%。": "Toute salle : temps de construction divisé par deux, {0} % des provisions remboursées à l'achèvement. Salle « Merveille » : remboursement porté à {1} %.",
"任何房间：所有防御塔伤害 +{0}%。契合「武器」：射程 +{1}，攻速 +{2}%。": "Toute salle : dégâts de toutes les tours de défense +{0} %. Salle « Arme » : portée +{1}, vit. d'attaque +{2} %.",
"任何房间：挖掘费用 -{0}%。契合「特殊」：所有建造少花 {1} 天。": "Toute salle : coût de fouille -{0} %. Salle « Spécial » : toutes les constructions prennent {1} j de moins.",
"任何房间：每场战斗初始积分倍率 +{0}。契合「锻造」：打造的宝物品质必定 +{1}。": "Toute salle : multiplicateur de points de départ +{0} à chaque combat. Salle « Forge » : les reliques forgées ont toujours +{1} de qualité.",
"任何房间：领袖技能冷却少 {0} 个节点。契合「运势」：出征开局多带 {1} 个支援道具（至少转出「史诗」效果）。": "Toute salle : recharge de la compétence du chef -{0} étape(s). Salle « Fortune » : objets de soutien au départ +{1} (effets au moins « Épique »).",
"任何房间：领袖攻击 +{0}%。契合「武器」：伤害 +{1}%，每次攻击放出连锁闪电（跳 {2} 个敌人）。": "Toute salle : attaque du chef +{0} %. Salle « Arme » : dégâts +{1} %, chaque attaque lance un éclair en chaîne ({2} rebonds).",
"任何房间：领袖每天回复 {0}% 生命（不需要医院）。契合「医疗 / 水域」：医院回复 +{1}%；水域武器射程 +{2}。": "Toute salle : votre chef récupère {0} % de PV par jour (sans hôpital). Salle « Médical / Eaux » : soins de l'hôpital +{1} % ; portée des armes aquatiques +{2}.",
"任何房间：领袖每天获得 {0} 经验。契合「生产」：这个房间自己的产出 ×{1}。": "Toute salle : votre chef gagne {0} XP par jour. Salle « Production » : production propre de cette salle ×{1}.",
