"前面是": "Devant vous :",
"前面是「墓园」：雾最浓的地方是镇外的墓园，新坟一夜比一夜多。": "Devant vous : « Cimetière ». Le brouillard y est le plus épais, et les tombes fraîches s'y multiplient chaque nuit.",
"前面是「总装车间」：工厂最后造出来的东西，把工厂里的人都装了进去。": "Devant vous : « Atelier d'assemblage ». La dernière chose que l'usine a fabriquée a enfermé tous ses ouvriers.",
"前面是「手术室」：院长说手术很成功，病人只是还没醒。": "Devant vous : « Bloc opératoire ». Le directeur dit que l'opération a réussi — le patient ne s'est simplement pas encore réveillé.",
"前面是「海底」：港口下面还有一座城，城门是一张嘴。": "Devant vous : « Fonds marins ». Sous le port se trouve une autre ville, et sa porte est une bouche.",
"前面是「知识古树」：古树记得森林里发生过的每一件事，它不想再记住别的了。": "Devant vous : « Arbre du savoir ». Il se souvient de tout ce qui s'est passé dans la forêt, et ne veut plus rien retenir d'autre.",
"前面是「精灵女王」：女王在月池边等了三百年。她说，你就是她等的那个人。": "Devant vous : « Reine elfe ». Elle attend au bord du bassin de lune depuis trois cents ans. Elle dit que c'est vous qu'elle attendait.",
"前面是「马戏大棚」：大棚里的笑声从来没停过，只是再也没有观众。": "Devant vous : « Chapiteau ». Les rires n'y ont jamais cessé, mais il n'y a plus de public.",
